arguments.command:
cd /workspace && python3 -c "
import json
with open('results/run100/metrics.jsonl') as f:
    for line in f:
        d = json.loads(line)
        step = d['step']
        data = d['data']
        keys = ['val-core/openai/gsm8k/acc/mean@1','val-aux/openai/gsm8k/reward/mean@1','train/val_core/mean@1']
        out = {}
        for k in list(data.keys()):
            if 'val' in k or 'score' in k or 'reward' in k or 'acc' in k:
                out[k] = data[k]
        # only print steps that have val-core acc or are multiples of 10 or step 0
        if 'val-core/openai/gsm8k/acc/mean@1' in data or 'val-core/mean@1' in data:
            print(step, json.dumps(out))
"

