import json, re
box=re.compile(r'\\\\boxed\s*\{([^{}]*)\}')
seen=set()
for step in [0,50,100]:
    with open(f'results/run100/val_generations/{step}.jsonl') as f:
        for line in f:
            d=json.loads(line); o=d['output']
            for m in box.finditer(o):
                seen.add(m.group(1))
print('num distinct boxed contents:', len(seen))
for s in list(seen)[:40]: print(repr(s))
"

